160	/**
161	 * 배송 상태 배치 처리를 위한 ItemProcessor
162	 * 주문 배송 상태를 조회하고 처리합니다.
163	 */
164	@Slf4j
165	public class ShipmentItemProcessor implements ItemProcessor<OrderShipment, OrderShipment> {
166	
167	    private final PlaywrightBrowserManager browserManager;
168	    private final NotificationCommandService notificationService;
169	    private final OrderShipmentCommandService orderService;
170	
171	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
172	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
173	    private static final int TIMEOUT_MS = 30000; // 30초
174	
175	    /**
176	     * 배송 상태 처리기 생성자
177	     *
178	     * @param browserManager Playwright 브라우저 관리자
179	     * @param notificationService 알림 서비스
180	     * @param orderService 주문 서비스
181	     */
182	    public ShipmentItemProcessor(
183	            PlaywrightBrowserManager browserManager,
184	            NotificationCommandService notificationService,
185	            OrderShipmentCommandService orderService
186	    ) {
187	        this.browserManager = browserManager;
188	        this.notificationService = notificationService;
189	        this.orderService = orderService;
190	    }
