160	/**
161	 * 배송 상태 배치 처리를 위한 ItemProcessor
162	 * 주문 배송 상태를 조회하고 처리합니다.
163	 */
164	@Slf4j
165	public class ShipmentItemProcessor implements ItemProcessor<OrderShipment, OrderShipment> {
166	
167	    private final PlaywrightBrowserManager browserManager;
168	    private final NotificationCommandService notificationService;
169	    private final OrderShipmentCommandService orderService;
170	
171	    private static final String TRACKING_URL_PREFIX = "https://trace.cjlogistics.com/next/tracking.html?wblNo=";
172	    private static final String STATUS_SELECTOR = "tbody#statusDetail tr";
173	    private static final int TIMEOUT_MS = 30000; // 30초
174	
175	    /**
176	     * 배송 상태 처리기 생성자
177	     *
178	     * @param browserManager Playwright 브라우저 관리자
179	     * @param notificationService 알림 서비스
180	     * @param orderService 주문 서비스
181	     */
182	    public ShipmentItemProcessor(
183	            PlaywrightBrowserManager browserManager,
184	            NotificationCommandService notificationService,
185	            OrderShipmentCommandService orderService
186	    ) {
187	        this.browserManager = browserManager;
188	        this.notificationService = notificationService;
189	        this.orderService = orderService;
190	    }
191	
192	    /**
193	     * 주문 배송의 상태를 외부 서비스를 통해 조회하고 업데이트합니다.
194	     *
195	     * @param orderShipment 처리할 배송 정보
196	     * @return 업데이트된 배송 정보
197	     * @throws Exception 처리 중 오류 발생 시
198	     */
199	    @Override
200	    public OrderShipment process(OrderShipment orderShipment) throws Exception {
201	        String trackingNumber = orderShipment.getTrackingNumber();
202	        Long shipmentId = orderShipment.getId();
203	
204	        if (trackingNumber == null || trackingNumber.isBlank()) {
205	            log.warn("유효하지 않은 운송장 번호: shipmentId={}", shipmentId);
206	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
207	        }
208	
209	        log.info("배송 상태 처리 시작: shipmentId={}, trackingNumber={}, currentStatus={}",
210	                shipmentId, trackingNumber, orderShipment.getStatus());
211	
212	        Page page = null;
213	        try {
214	            // browserManager를 통해 페이지 생성
215	            page = browserManager.newPage();
216	            if (page == null) {
217	                throw new ShipmentException(ShipmentErrorCode.BROWSER_INITIALIZATION_ERROR);
218	            }
219	
220	            // 타임아웃 설정
221	            page.setDefaultTimeout(TIMEOUT_MS);
222	
223	            // 배송 추적 URL로 이동
224	            String url = TRACKING_URL_PREFIX + trackingNumber;
225	            log.debug("배송 조회 페이지로 이동: {}", url);
226	            page.navigate(url);
227	
228	            // 배송 상태 테이블 로드 대기
229	            log.debug("배송 상태 테이블 로드 대기");
230	            page.waitForSelector(STATUS_SELECTOR);
231	
232	            // 최종 HTML 가져오기
233	            String renderedHtml = page.content();
234	            log.debug("페이지 HTML 로드 완료 (길이: {})", renderedHtml.length());
235	
236	            // HTML 파싱하여 배송 상태 추출
237	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
238	            ShipmentStatus newStatus = mapToShipmentStatus(statusText);
239	
240	            log.debug("배송 상태 조회 결과: shipmentId={}, statusText={}, mappedStatus={}",
241	                    shipmentId, statusText, newStatus);
242	
243	            // 현재 상태와 동일한 경우 중복 처리 방지
244	            if (orderShipment.getStatus() == newStatus) {
245	                log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
246	                        shipmentId, newStatus);
247	                return orderShipment;
248	            }
249	
250	            // 상태에 따른 처리
251	            if (newStatus == ShipmentStatus.DELIVERED) {
252	                log.info("배송 완료 처리: shipmentId={}, orderId={}",
253	                        shipmentId, orderShipment.getOrder().getId());
254	
255	                // 배송 상태 업데이트
256	                orderShipment.updateStatus(ShipmentStatus.DELIVERED);
257	
258	                // 주문 완료 처리 및 알림
259	                orderService.completeOrder(orderShipment.getOrder().getId());
260	                notificationService.notifyShipmentCompleted(orderShipment.getOrder());
261	
262	            } else if (newStatus == ShipmentStatus.OUT_FOR_DELIVERY) {
263	                log.info("배송 출발 처리: shipmentId={}", shipmentId);
264	                orderShipment.updateStatus(ShipmentStatus.OUT_FOR_DELIVERY);
265	
266	            } else {
267	                log.info("배송 중 상태 업데이트: shipmentId={}", shipmentId);
268	                orderShipment.updateStatus(ShipmentStatus.IN_TRANSIT);
269	            }
270	
271	            log.info("배송 상태 처리 완료: shipmentId={}, newStatus={}",
272	                    shipmentId, orderShipment.getStatus());
273	
274	            return orderShipment;
275	
276	        } catch (Exception e) {
277	            log.error("배송 상태 처리 중 오류 발생: shipmentId={}, trackingNumber={}, error={}",
278	                    shipmentId, trackingNumber, e.getMessage(), e);
279	
280	            // ShipmentException 타입이 아닌 경우 래핑
281	            if (!(e instanceof ShipmentException)) {
282	                throw new ShipmentException(
283	                        ShipmentErrorCode.EXTERNAL_TRACKING_SERVICE_ERROR,
284	                        "배송 상태 조회 중 오류 발생: " + e.getMessage(),
285	                        e
286	                );
287	            }
288	            throw e;
289	        } finally {
290	            // 페이지 리소스 해제
291	            if (page != null) {
292	                try {
293	                    page.close();
294	                    log.debug("페이지 리소스 해제 완료");
295	                } catch (Exception e) {
296	                    log.warn("페이지 닫기 실패: {}", e.getMessage());
297	                }
298	            }
299	        }
300	    }
301	
302	    /**
303	     * HTML에서 배송 상태를 파싱합니다.
304	     *
305	     * @param html 파싱할 HTML 문자열
306	     * @param trackingNumber 로깅용 운송장 번호
307	     * @return 배송 상태 문자열
308	     * @throws ShipmentException 파싱 실패 시 발생
309	     */
310	    private String parseStatusFromHtml(String html, String trackingNumber) {
311	        try {
312	            Document doc = Jsoup.parse(html);
313	            Elements rows = doc.select(STATUS_SELECTOR);
314	
315	            if (rows.isEmpty()) {
316	                log.warn("배송 상태 테이블이 비어 있음: 운송장={}", trackingNumber);
317	                throw new ShipmentException(
318	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
319	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
320	                );
321	            }
322	
323	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
324	            String statusText = rows.last().select("td").get(4).text().trim();
325	
326	            if (statusText.isEmpty()) {
327	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
328	                throw new ShipmentException(
329	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
330	                        "배송 상태 정보를 찾을 수 없습니다."
331	                );
332	            }
333	
334	            return statusText;
335	
336	        } catch (IndexOutOfBoundsException e) {
337	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
338	            throw new ShipmentException(
339	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
340	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
341	                    e
342	            );
343	        } catch (Exception e) {
344	            if (e instanceof ShipmentException) {
345	                throw (ShipmentException) e;
346	            }
347	
348	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
349	            throw new ShipmentException(
350	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
351	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
352	                    e
353	            );
354	        }
355	    }
356	
357	    /**
358	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
359	     *
360	     * @param statusText 배송사 상태 텍스트
361	     * @return 매핑된 ShipmentStatus
362	     */
363	    private ShipmentStatus mapToShipmentStatus(String statusText) {
364	        return switch (statusText) {
365	            case "배송완료" -> ShipmentStatus.DELIVERED;
366	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
367	            default -> ShipmentStatus.IN_TRANSIT;
368	        };
369	    }
