403	/**
404	 * 배송 상태 자동 업데이트를 위한 배치 작업 구성
405	 */
406	@Slf4j
407	@Configuration
408	@RequiredArgsConstructor
409	public class UpdateShipmentStatusesJobConfig {
410	
411	    private final JobRepository jobRepository;
412	    private final PlatformTransactionManager transactionManager;
413	    private final EntityManagerFactory entityManagerFactory;
414	
415	    private final OrderShipmentRepository orderShipmentRepository;
416	    private final NotificationCommandService notificationService;
417	    private final OrderShipmentCommandService orderService;
418	    private final CjTrackingPlaywright cjTrackingPlaywright;
419	
420	    private static final int CHUNK_SIZE = 50;
421	    private static final int SKIP_LIMIT = 50;
422	
423	    @Bean
424	    public Job updateShipmentStatusesJob() {
425	        log.info("배송 상태 업데이트 작업 구성");
426	        return new JobBuilder("updateShipmentStatusesJob", jobRepository)
427	                .start(updateShipmentStatusesStep())
428	                .build();
429	    }
430	
431	    @Bean
432	    public Step updateShipmentStatusesStep() {
433	        log.info("배송 상태 업데이트 스텝 구성: 청크 크기={}, 스킵 제한={}", CHUNK_SIZE, SKIP_LIMIT);
434	
435	        return new StepBuilder("updateShipmentStatusesStep", jobRepository)
436	                .<OrderShipment, OrderShipment>chunk(CHUNK_SIZE, transactionManager)
437	                .reader(shipmentItemReader())
438	                .processor(new ShipmentItemProcessor(
439	                        playwrightBrowserManager(), // Bean or new
440	                        notificationService,
441	                        orderService
442	                ))
443	                .writer(shipmentJpaItemWriter())
444	                .faultTolerant()
445	                .skip(Exception.class)
446	                .skipLimit(SKIP_LIMIT)
447	                .listener(shipmentSkipListener())
448	                // ★ Step Execution Listener로 Browser 관리 리스너 추가
449	                .listener(new BrowserManageStepListener(playwrightBrowserManager()))
450	                .build();
451	    }
